// ============================================================
// Transformation Parameters
// ============================================================
//
// These are semantic transformation parameters,
// not direct matrix-element controls.
//
// Initial parameters reproduce:
//
//     [ 1   2   -0.2 ]
// A = [ 0   1    0   ]
//     [ 0   0    1   ]
//
// because:
//
// rotation = 0
// scale    = identity
//
// H =
// [ 1  shXY  shXZ ]
// [ 0   1    shYZ ]
// [ 0   0      1  ]
//
// ============================================================

const exampleParameters = {

    scaleX: 1,
    scaleY: 1,
    scaleZ: 1,

    rotateX: 0,
    rotateY: 0,
    rotateZ: 0,

    shearXY: 2,
    shearXZ: -0.2,
    shearYZ: 0
};


const identityParameters = {

