// ============================================================
// Transform Point
// ============================================================
//
// q = A · p
//
// p = [x, y, z]^T
//
// ============================================================

function transformPoint(
    x,
    y,
    z
) {

    return [

        A[0][0] * x +
        A[0][1] * y +
        A[0][2] * z,

        A[1][0] * x +
        A[1][1] * y +
        A[1][2] * z,

        A[2][0] * x +
        A[2][1] * y +
        A[2][2] * z
    ];
}


// ============================================================
// Camera
// ============================================================

const camera = {

    yaw:
        -35 *
        Math.PI /
        180,

    pitch:
        24 *
        Math.PI /
        180,

    distance:
        7,

    focal:
        600,

    centerX:
        canvas.width *
        0.5,

    centerY:
        canvas.height *
        0.53
};


// ============================================================
// 3D -&gt; 2D Projection
// ============================================================

function projectPoint(
    point
) {

    let [x, y, z] =
        point;


    // Camera yaw
    const cy =
        Math.cos(
            camera.yaw
        );

    const sy =
        Math.sin(
            camera.yaw
        );


    const x1 =
        cy * x -
        sy * y;

    const y1 =
        sy * x +
        cy * y;

    const z1 =
        z;


    // Camera pitch
    const cp =
        Math.cos(
            camera.pitch
        );

    const sp =
        Math.sin(
            camera.pitch
        );


    const x2 =
        x1;

    const y2 =
        cp * y1 -
        sp * z1;

    const z2 =
        sp * y1 +
        cp * z1;


    // Perspective projection
    const depth =
        camera.distance -
        z2;


    if (
        depth &lt;=
        0.15
    ) {

        return null;
    }


    const scale =
        camera.focal /
        depth;


    return [

        camera.centerX +
        x2 * scale,

        camera.centerY -
        y2 * scale,

        depth
    ];
}


