// ============================================================
// World Line
// ============================================================

function drawWorldLine(
    p1,
    p2,
    color,
    width = 1,
    dash = []
) {

    const a =
        projectPoint(
            p1
        );

    const b =
        projectPoint(
            p2
        );


    if (
        !a ||
        !b
    ) {

        return;
    }


    ctx.save();

    ctx.beginPath();

    ctx.moveTo(
        a[0],
        a[1]
    );

    ctx.lineTo(
        b[0],
        b[1]
    );


    ctx.strokeStyle =
        color;

    ctx.lineWidth =
        width;

    ctx.setLineDash(
        dash
    );

    ctx.stroke();

    ctx.restore();
}


// ============================================================
// Axes
// ============================================================

function drawAxes() {

    const axisLength =
        3.0;


    // X axis
    drawWorldLine(

        [-axisLength, 0, 0],

        [axisLength, 0, 0],

        &quot;rgba(220,80,80,0.9)&quot;,

        1.7
    );


    // Y axis
    drawWorldLine(

        [0, -axisLength, 0],

        [0, axisLength, 0],

        &quot;rgba(70,170,90,0.9)&quot;,

        1.7
    );


    // Z axis
    drawWorldLine(

        [0, 0, -2],

        [0, 0, axisLength],

        &quot;rgba(70,120,230,0.9)&quot;,

        1.7
    );


    const xLabel =
        projectPoint(
            [
                axisLength +
                0.15,

                0,

                0
            ]
        );


    const yLabel =
        projectPoint(
            [
                0,

                axisLength +
                0.15,

                0
            ]
        );


    const zLabel =
        projectPoint(
            [
                0,

                0,

                axisLength +
                0.15
            ]
        );


    ctx.save();

    ctx.font =
        &quot;15px sans-serif&quot;;


    if (xLabel) {

        ctx.fillStyle =
            &quot;rgba(220,80,80,0.95)&quot;;

        ctx.fillText(
            &quot;x&quot;,
            xLabel[0],
            xLabel[1]
        );
    }


    if (yLabel) {

        ctx.fillStyle =
            &quot;rgba(70,170,90,0.95)&quot;;

        ctx.fillText(
            &quot;y&quot;,
            yLabel[0],
            yLabel[1]
        );
    }


    if (zLabel) {

        ctx.fillStyle =
            &quot;rgba(70,120,230,0.95)&quot;;

        ctx.fillText(
            &quot;z&quot;,
            zLabel[0],
            zLabel[1]
        );
    }


    ctx.restore();
}


// ============================================================
// Texture
// ============================================================

let texture = null;
let textureName = null;


// ============================================================
// Plane Size
// ============================================================

function getPlaneSize() {

    if (!texture) {

        return {
            width: 2.4,
            height: 1.6
        };
    }


    const aspect =
        texture.width /
        texture.height;


    let width =
        2.5;

    let height =
        width /
        aspect;


    if (
        height &gt;
        2.0
    ) {

        height =
            2.0;

        width =
            height *
            aspect;
    }


    return {
        width,
        height
    };
}


// ============================================================
// Original Image Plane
//
// The image lies on z = 1.
//
// This keeps all three coordinates non-trivial
// and allows the full 3D linear transformation
// to affect the plane.
// ============================================================

function localPlanePoint(
    u,
    v
) {

    const size =
        getPlaneSize();


    return [

        (u - 0.5) *
        size.width,

        (0.5 - v) *
        size.height,

        1
    ];
}


// ============================================================
// Transformed Image Plane
// ============================================================

function transformedPlanePoint(
    u,
    v
) {

    const p =
        localPlanePoint(
            u,
            v
        );


    return transformPoint(
        p[0],
        p[1],
        p[2]
    );
}


// ============================================================
// Reference Plane
// ============================================================

function drawReferencePlane() {

    const size =
        getPlaneSize();


    const corners = [

        [
            -size.width / 2,
            -size.height / 2,
            1
        ],

        [
            size.width / 2,
            -size.height / 2,
            1
        ],

        [
            size.width / 2,
            size.height / 2,
            1
        ],

        [
            -size.width / 2,
            size.height / 2,
            1
        ]
    ];


    const projected =
        corners.map(
            projectPoint
        );


    if (
        projected.some(
            p =&gt; !p
        )
    ) {

        return;
    }


    ctx.save();

    ctx.beginPath();


    ctx.moveTo(

        projected[0][0],

        projected[0][1]
    );


    for (
        let i = 1;
        i &lt; projected.length;
        i++
    ) {

        ctx.lineTo(

            projected[i][0],

            projected[i][1]
        );
    }


    ctx.closePath();


    ctx.strokeStyle =
        &quot;rgba(130,130,130,0.35)&quot;;

    ctx.lineWidth =
        1;

    ctx.setLineDash(
        [5, 5]
    );

    ctx.stroke();

    ctx.restore();
}


// ============================================================
// Triangle Texture Mapping
// ============================================================

function drawTexturedTriangle(
    source,
    src0,
    src1,
    src2,
    dst0,
    dst1,
    dst2
) {

    if (
        !dst0 ||
        !dst1 ||
        !dst2
    ) {

        return;
    }


    const x0 =
        src0[0];

    const y0 =
        src0[1];


    const x1 =
        src1[0];

    const y1 =
        src1[1];


    const x2 =
        src2[0];

    const y2 =
        src2[1];


    const dx1 =
        x1 - x0;

    const dy1 =
        y1 - y0;


    const dx2 =
        x2 - x0;

    const dy2 =
        y2 - y0;


    const determinant =
        dx1 * dy2 -
        dx2 * dy1;


    if (
        Math.abs(
            determinant
        ) &lt;
        1e-8
    ) {

        return;
    }


    const invDet =
        1 /
        determinant;


    const a = (

        (dst1[0] - dst0[0]) *
        dy2 -

        (dst2[0] - dst0[0]) *
        dy1

    ) * invDet;


    const c = (

        dx1 *
        (dst2[0] - dst0[0]) -

        dx2 *
        (dst1[0] - dst0[0])

    ) * invDet;


    const e =
        dst0[0] -
        a * x0 -
        c * y0;


    const b = (

        (dst1[1] - dst0[1]) *
        dy2 -

        (dst2[1] - dst0[1]) *
        dy1

    ) * invDet;


    const d = (

        dx1 *
        (dst2[1] - dst0[1]) -

        dx2 *
        (dst1[1] - dst0[1])

    ) * invDet;


    const f =
        dst0[1] -
        b * x0 -
        d * y0;


    ctx.save();

    ctx.beginPath();


    ctx.moveTo(
        dst0[0],
        dst0[1]
    );

    ctx.lineTo(
        dst1[0],
        dst1[1]
    );

    ctx.lineTo(
        dst2[0],
        dst2[1]
    );


    ctx.closePath();

    ctx.clip();


    ctx.setTransform(
        a,
        b,
        c,
        d,
        e,
        f
    );


    ctx.drawImage(
        source,
        0,
        0
    );


    ctx.restore();
}


// ============================================================
// Draw Transformed Texture
// ============================================================

function drawTransformedTexture() {

    if (!texture) {

        drawPlaceholderPlane();

        return;
    }


    const cols =
        24;

    const rows =
        18;


    for (
        let row = 0;
        row &lt; rows;
        row++
    ) {

        for (
            let col = 0;
            col &lt; cols;
            col++
        ) {

            const u0 =
                col /
                cols;

            const u1 =
                (col + 1) /
                cols;


            const v0 =
                row /
                rows;

            const v1 =
                (row + 1) /
                rows;


            const w00 =
                transformedPlanePoint(
                    u0,
                    v0
                );


            const w10 =
                transformedPlanePoint(
                    u1,
                    v0
                );


            const w01 =
                transformedPlanePoint(
                    u0,
                    v1
                );


            const w11 =
                transformedPlanePoint(
                    u1,
                    v1
                );


            const p00 =
                projectPoint(
                    w00
                );

            const p10 =
                projectPoint(
                    w10
                );

            const p01 =
                projectPoint(
                    w01
                );

            const p11 =
                projectPoint(
                    w11
                );


            if (
                !p00 ||
                !p10 ||
                !p01 ||
                !p11
            ) {

                continue;
            }


            const sx0 =
                u0 *
                texture.width;

            const sx1 =
                u1 *
                texture.width;


            const sy0 =
                v0 *
                texture.height;

            const sy1 =
                v1 *
                texture.height;


            drawTexturedTriangle(

                texture,

                [sx0, sy0],

                [sx1, sy0],

                [sx0, sy1],

                p00,
                p10,
                p01
            );


            drawTexturedTriangle(

                texture,

                [sx1, sy0],

                [sx1, sy1],

                [sx0, sy1],

                p10,
                p11,
                p01
            );
        }
    }
}


