// ============================================================
// Plane Grid
// ============================================================

function drawPlaneGrid() {

    const gridCount =
        6;


    for (
        let i = 0;
        i &lt;= gridCount;
        i++
    ) {

        const t =
            i /
            gridCount;


        drawProjectedPlaneLine(
            t,
            0,
            t,
            1
        );


        drawProjectedPlaneLine(
            0,
            t,
            1,
            t
        );
    }
}


// ============================================================
// Grid Line
// ============================================================

function drawProjectedPlaneLine(
    u0,
    v0,
    u1,
    v1
) {

    const segments =
        20;


    ctx.beginPath();


    let started =
        false;


    for (
        let i = 0;
        i &lt;= segments;
        i++
    ) {

        const t =
            i /
            segments;


        const u =
            u0 +
            (u1 - u0) *
            t;


        const v =
            v0 +
            (v1 - v0) *
            t;


        const world =
            transformedPlanePoint(
                u,
                v
            );


        const screen =
            projectPoint(
                world
            );


        if (!screen) {

            started =
                false;

            continue;
        }


        if (!started) {

            ctx.moveTo(
                screen[0],
                screen[1]
            );


            started =
                true;

        } else {

            ctx.lineTo(
                screen[0],
                screen[1]
            );
        }
    }


    ctx.strokeStyle =
        texture
            ? &quot;rgba(255,255,255,0.32)&quot;
            : &quot;rgba(80,80,80,0.35)&quot;;


    ctx.lineWidth =
        0.8;


    ctx.stroke();
}


