// ============================================================
// Texture Preprocessing
// ============================================================

function setTextureFromImage(
    image,
    name
) {

    const maxSize =
        1200;


    let width =
        image.naturalWidth ||
        image.width;


    let height =
        image.naturalHeight ||
        image.height;


    if (
        width &gt;
        maxSize ||
        height &gt;
        maxSize
    ) {

        const ratio =
            Math.min(

                maxSize /
                width,

                maxSize /
                height
            );


        width =
            Math.round(
                width *
                ratio
            );


        height =
            Math.round(
                height *
                ratio
            );
    }


    const offscreen =
        document.createElement(
            &quot;canvas&quot;
        );


    offscreen.width =
        width;

    offscreen.height =
        height;


    const offCtx =
        offscreen.getContext(
            &quot;2d&quot;
        );


    offCtx.imageSmoothingEnabled =
        true;


    offCtx.imageSmoothingQuality =
        &quot;high&quot;;


    offCtx.drawImage(
        image,
        0,
        0,
        width,
        height
    );


    texture =
        offscreen;


    textureName =
        name;


    imageStatus.textContent =
        `Selected image: ${name}`;


    scheduleRender();
}


