                );


        if (!file) {

            imageStatus.textContent =
                &quot;The saved image no longer exists.&quot;;

            return;
        }


        const resourcePath =
            app.vault
                .getResourcePath(
                    file
                );


        vaultSelect.value =
            path;


        loadImageSource(
            resourcePath,
            file.name
        );


        if (save) {

            saveSelectedImagePath(
                path
            );
        }

    } catch (error) {

        console.error(
            &quot;Vault image loading failed:&quot;,
            error
        );


        imageStatus.textContent =
            &quot;Could not load the selected Vault image.&quot;;
    }
}


